create sequence if not exists goods_receipt_number_seq;
create table goods_receipts(id bigint generated by default as identity primary key,tenant_id bigint not null references tenants(id),company_id bigint not null references companies(id),branch_id bigint not null references branches(id),purchase_order_id bigint not null references purchase_orders(id),supplier_id bigint not null references suppliers(id),receipt_number varchar(64) not null,received_at timestamptz not null default now(),status varchar(16) not null default 'DRAFT',warehouse_id bigint,notes varchar(2000),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version bigint not null default 0,unique(tenant_id,receipt_number),check(status in ('DRAFT','CONFIRMED','CANCELLED')));
create table goods_receipt_lines(id bigint generated by default as identity primary key,tenant_id bigint not null references tenants(id),receipt_id bigint not null references goods_receipts(id) on delete cascade,purchase_order_line_id bigint not null references purchase_order_lines(id),product_id bigint not null references products(id),received_quantity numeric(18,3) not null,unit_cost numeric(18,2) not null,check(received_quantity>0 and unit_cost>=0),unique(receipt_id,purchase_order_line_id));
create index goods_receipts_scope_idx on goods_receipts(tenant_id,company_id,branch_id,status);
